//! Signed release manifests (design 5a step 2, 10; S6 and L5 groundwork).
//!
//! ```text
//! signed message = "spark-link/release/v1" || manifest_json (exact UTF-8 bytes)
//! signature      = Ed25519 by a pinned release key; base64url in `sig`
//! ```
//! The agent verifies the node binary's manifest (signature, target, sha256,
//! expiry) before upload and re-verifies the SHA-256 on the Spark after upload.
//! No production release key exists yet (owner action); builds take trusted
//! keys from configuration and tests use keys generated by spark-link-testkit.

use ed25519_dalek::{Signature, Verifier, VerifyingKey};
use serde::{Deserialize, Serialize};

use crate::ids::b64url_decode_exact;
use crate::version::parse_semver;

pub const RELEASE_DOMAIN: &[u8] = b"spark-link/release/v1";

#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "kebab-case")]
pub enum Product {
    SparkLinkNode,
    SparkLinkAgent,
}

#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
pub struct ReleaseManifest {
    pub product: Product,
    /// Plain MAJOR.MINOR.PATCH.
    pub version: String,
    /// Rust target triple, e.g. `aarch64-unknown-linux-gnu`.
    pub target: String,
    /// hex SHA-256 of the binary
    pub sha256: String,
    pub size: u64,
    pub min_secure_version: String,
    pub issued_at: u64,
    pub expires_at: u64,
}

#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
pub struct SignedManifest {
    /// Exact JSON text that was signed.
    pub manifest_json: String,
    /// base64url Ed25519 signature (64 bytes)
    pub sig: String,
}

#[derive(Debug, thiserror::Error, PartialEq, Eq)]
pub enum ReleaseError {
    #[error("manifest signature does not verify with any trusted key")]
    BadSignature,
    #[error("manifest is malformed")]
    Malformed,
    #[error("manifest expired")]
    Expired,
    #[error("manifest is for {0}, expected {1}")]
    WrongTarget(String, String),
    #[error("manifest is for a different product")]
    WrongProduct,
    #[error("version {0} is below the minimum secure version {1}")]
    BelowMinimum(String, String),
}

pub fn signing_message(manifest_json: &str) -> Vec<u8> {
    let mut m = Vec::with_capacity(RELEASE_DOMAIN.len() + manifest_json.len());
    m.extend_from_slice(RELEASE_DOMAIN);
    m.extend_from_slice(manifest_json.as_bytes());
    m
}

/// Verify signature, product, target, expiry and min_secure_version.
pub fn verify(signed: &SignedManifest, trusted_keys: &[[u8; 32]], product: Product, target: &str, now: u64) -> Result<ReleaseManifest, ReleaseError> {
    let sig = b64url_decode_exact::<64>(&signed.sig, "signature").map_err(|_| ReleaseError::Malformed)?;
    let sig = Signature::from_bytes(&sig);
    let msg = signing_message(&signed.manifest_json);
    let ok = trusted_keys.iter().any(|k| VerifyingKey::from_bytes(k).map(|vk| vk.verify(&msg, &sig).is_ok()).unwrap_or(false));
    if !ok {
        return Err(ReleaseError::BadSignature);
    }
    let m: ReleaseManifest = serde_json::from_str(&signed.manifest_json).map_err(|_| ReleaseError::Malformed)?;
    if m.product != product {
        return Err(ReleaseError::WrongProduct);
    }
    if m.target != target {
        return Err(ReleaseError::WrongTarget(m.target.clone(), target.to_string()));
    }
    if now >= m.expires_at {
        return Err(ReleaseError::Expired);
    }
    let (Some(v), Some(min)) = (parse_semver(&m.version), parse_semver(&m.min_secure_version)) else {
        return Err(ReleaseError::Malformed);
    };
    if v < min {
        return Err(ReleaseError::BelowMinimum(m.version.clone(), m.min_secure_version.clone()));
    }
    if m.sha256.len() != 64 || !m.sha256.bytes().all(|b| b.is_ascii_hexdigit() && !b.is_ascii_uppercase()) {
        return Err(ReleaseError::Malformed);
    }
    Ok(m)
}

/// `a > b` for plain semver strings; false if either is malformed.
pub fn is_newer(a: &str, b: &str) -> bool {
    match (parse_semver(a), parse_semver(b)) {
        (Some(x), Some(y)) => x > y,
        _ => false,
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use ed25519_dalek::{Signer, SigningKey};

    fn signed(sk: &SigningKey, m: &ReleaseManifest) -> SignedManifest {
        let manifest_json = serde_json::to_string(m).unwrap();
        let sig = sk.sign(&signing_message(&manifest_json));
        SignedManifest { manifest_json, sig: crate::ids::b64url(&sig.to_bytes()) }
    }

    fn manifest() -> ReleaseManifest {
        ReleaseManifest {
            product: Product::SparkLinkNode,
            version: "0.1.0".into(),
            target: "aarch64-unknown-linux-gnu".into(),
            sha256: "0".repeat(64),
            size: 1,
            min_secure_version: "0.1.0".into(),
            issued_at: 100,
            expires_at: 200,
        }
    }

    #[test]
    fn verify_rules() {
        let sk = SigningKey::from_bytes(&[1; 32]);
        let pk = sk.verifying_key().to_bytes();
        let s = signed(&sk, &manifest());
        assert!(verify(&s, &[pk], Product::SparkLinkNode, "aarch64-unknown-linux-gnu", 150).is_ok());
        assert_eq!(verify(&s, &[[7; 32]], Product::SparkLinkNode, "aarch64-unknown-linux-gnu", 150).unwrap_err(), ReleaseError::BadSignature);
        assert_eq!(verify(&s, &[pk], Product::SparkLinkNode, "aarch64-unknown-linux-gnu", 200).unwrap_err(), ReleaseError::Expired);
        assert!(matches!(verify(&s, &[pk], Product::SparkLinkNode, "x86_64-unknown-linux-gnu", 150), Err(ReleaseError::WrongTarget(..))));
        assert_eq!(verify(&s, &[pk], Product::SparkLinkAgent, "aarch64-unknown-linux-gnu", 150).unwrap_err(), ReleaseError::WrongProduct);
        let mut tampered = s.clone();
        tampered.manifest_json = tampered.manifest_json.replace("0.1.0", "9.9.9");
        assert_eq!(verify(&tampered, &[pk], Product::SparkLinkNode, "aarch64-unknown-linux-gnu", 150).unwrap_err(), ReleaseError::BadSignature);
        assert!(is_newer("1.0.1", "1.0.0") && !is_newer("1.0.0", "1.0.0") && !is_newer("x", "1.0.0"));
    }
}
